use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

    // append returns a new Vec equal to a with b appended,
    // without modifying the input Vec a.
    fn append(a: &Vec<i32>, b: i32) -> (res: Vec<i32>)
        ensures
            // In the post‐condition, a.view() refers to the original (pre‐state) contents of a.
            res.view() == old(a.view()) + Seq::singleton(b),
    {
        // Capture the original view of a for use in loop invariants.
        let a_view = a.view();

        // Allocate a new vector with capacity = original length + 1.
        let mut res: Vec<i32> = Vec::with_capacity(a_view.len() + 1);

        // We'll copy elements one by one.
        let mut i: usize = 0;
        while i < a_view.len()
            invariant
                // index stays in bounds
                i <= a_view.len(),
                // res.len() equals how many we've copied so far
                res.len() == i,
                // the prefix of res we've built equals the corresponding prefix of a_view
                res.view() == a_view.subrange(0, i as nat),
            decreases
                // we make progress in copying
                a_view.len() - i,
        {
            // safe because i < a_view.len()
            assert(a.get(i).is_Some());
            let v_ref = a.get(i).unwrap();
            let v: i32 = *v_ref;
            res.push(v);
            i += 1;
        }

        // finally append b
        res.push(b);

        res
    }
}

